using System;
using Customization;

public class UomRenamePieceToYds : CustomizationPlugin
{
    public override void UpdateDatabase()
    {
        WriteLog("=== UomRenamePieceToYds: Starting UOM relabel PIECE → YDS ===");

        var cs = System.Configuration.ConfigurationManager.ConnectionStrings["ProjectX"];
        if (cs == null)
        {
            WriteLog("ERROR: ConnectionString 'ProjectX' not found. Aborting.");
            return;
        }

        string connStr = cs.ConnectionString + ";TrustServerCertificate=True";
        int grandTotal = 0;

        using (var conn = new Microsoft.Data.SqlClient.SqlConnection(connStr))
        {
            conn.Open();
            WriteLog("Connected to database.");

            // ============================================================
            // SECTION 1: Core Item Configuration
            // ============================================================
            WriteLog("--- Section 1: Core Item Configuration ---");
            grandTotal += SafeExec(conn, "UPDATE InventoryItem SET BaseUnit = 'YDS' WHERE BaseUnit = 'PIECE'", "InventoryItem.BaseUnit");
            grandTotal += SafeExec(conn, "UPDATE InventoryItem SET SalesUnit = 'YDS' WHERE SalesUnit = 'PIECE'", "InventoryItem.SalesUnit");
            grandTotal += SafeExec(conn, "UPDATE INItemClass SET BaseUnit = 'YDS' WHERE BaseUnit = 'PIECE'", "INItemClass.BaseUnit");
            grandTotal += SafeExec(conn, "UPDATE INItemClass SET SalesUnit = 'YDS' WHERE SalesUnit = 'PIECE'", "INItemClass.SalesUnit");

            // ============================================================
            // SECTION 2: UOM Conversions
            // ============================================================
            WriteLog("--- Section 2: UOM Conversions ---");
            grandTotal += SafeExec(conn, "UPDATE INUnit SET FromUnit = 'YDS' WHERE FromUnit = 'PIECE'", "INUnit.FromUnit");
            grandTotal += SafeExec(conn, "UPDATE INUnit SET ToUnit = 'YDS' WHERE ToUnit = 'PIECE'", "INUnit.ToUnit");
            // Clean up self-referencing conversions (YDS → YDS with rate 1.0)
            grandTotal += SafeExec(conn, "DELETE FROM INUnit WHERE FromUnit = 'YDS' AND ToUnit = 'YDS' AND UnitRate = 1", "INUnit.SelfRef.Cleanup");

            // ============================================================
            // SECTION 3: Inventory Transactions
            // ============================================================
            WriteLog("--- Section 3: Inventory Transactions ---");
            grandTotal += SafeExec(conn, "UPDATE INTran SET UOM = 'YDS' WHERE UOM = 'PIECE'", "INTran.UOM");
            grandTotal += SafeExec(conn, "UPDATE INTranSplit SET UOM = 'YDS' WHERE UOM = 'PIECE'", "INTranSplit.UOM");

            // ============================================================
            // SECTION 4: Sales Orders & Shipments
            // ============================================================
            WriteLog("--- Section 4: Sales Orders & Shipments ---");
            grandTotal += SafeExec(conn, "UPDATE SOLine SET UOM = 'YDS' WHERE UOM = 'PIECE'", "SOLine.UOM");
            grandTotal += SafeExec(conn, "UPDATE SOLineSplit SET UOM = 'YDS' WHERE UOM = 'PIECE'", "SOLineSplit.UOM");
            grandTotal += SafeExec(conn, "UPDATE SOShipLine SET UOM = 'YDS' WHERE UOM = 'PIECE'", "SOShipLine.UOM");
            grandTotal += SafeExec(conn, "UPDATE SOShipLineSplit SET UOM = 'YDS' WHERE UOM = 'PIECE'", "SOShipLineSplit.UOM");
            grandTotal += SafeExec(conn, "UPDATE SOPackageDetailEx SET UOM = 'YDS' WHERE UOM = 'PIECE'", "SOPackageDetailEx.UOM");

            // ============================================================
            // SECTION 5: Purchase Orders & Receipts
            // ============================================================
            WriteLog("--- Section 5: Purchase Orders & Receipts ---");
            grandTotal += SafeExec(conn, "UPDATE POLine SET UOM = 'YDS' WHERE UOM = 'PIECE'", "POLine.UOM");
            grandTotal += SafeExec(conn, "UPDATE POLineSplit SET UOM = 'YDS' WHERE UOM = 'PIECE'", "POLineSplit.UOM");
            grandTotal += SafeExec(conn, "UPDATE POReceiptLine SET UOM = 'YDS' WHERE UOM = 'PIECE'", "POReceiptLine.UOM");
            grandTotal += SafeExec(conn, "UPDATE POReceiptLineSplit SET UOM = 'YDS' WHERE UOM = 'PIECE'", "POReceiptLineSplit.UOM");

            // ============================================================
            // SECTION 6: AR / AP Transactions
            // ============================================================
            WriteLog("--- Section 6: AR / AP Transactions ---");
            grandTotal += SafeExec(conn, "UPDATE ARTran SET UOM = 'YDS' WHERE UOM = 'PIECE'", "ARTran.UOM");
            grandTotal += SafeExec(conn, "UPDATE APTran SET UOM = 'YDS' WHERE UOM = 'PIECE'", "APTran.UOM");

            // ============================================================
            // SECTION 7: Price Lists
            // ============================================================
            WriteLog("--- Section 7: Price Lists ---");
            grandTotal += SafeExec(conn, "UPDATE ARSalesPrice SET UOM = 'YDS' WHERE UOM = 'PIECE'", "ARSalesPrice.UOM");
            grandTotal += SafeExec(conn, "UPDATE APVendorPrice SET UOM = 'YDS' WHERE UOM = 'PIECE'", "APVendorPrice.UOM");

            // ============================================================
            // SECTION 8: Physical Inventory & Kits
            // ============================================================
            WriteLog("--- Section 8: Physical Inventory & Kits ---");
            grandTotal += SafeExec(conn, "UPDATE INPIDetail SET UOM = 'YDS' WHERE UOM = 'PIECE'", "INPIDetail.UOM");
            grandTotal += SafeExec(conn, "UPDATE INKitSpecStkDet SET UOM = 'YDS' WHERE UOM = 'PIECE'", "INKitSpecStkDet.UOM");
            grandTotal += SafeExec(conn, "UPDATE INKitSpecNonStkDet SET UOM = 'YDS' WHERE UOM = 'PIECE'", "INKitSpecNonStkDet.UOM");

            // ============================================================
            // SECTION 9: Inventory Planning & Status (UOM references)
            // ============================================================
            WriteLog("--- Section 9: Inventory Planning & Status ---");
            grandTotal += SafeExec(conn, "UPDATE INItemPlan SET UOM = 'YDS' WHERE UOM = 'PIECE'", "INItemPlan.UOM");
            grandTotal += SafeExec(conn, "UPDATE INItemCustSalesStats SET BaseUOM = 'YDS' WHERE BaseUOM = 'PIECE'", "INItemCustSalesStats.BaseUOM");

            // ============================================================
            // SECTION 10: Lot/Serial Class Rename (PIECENBR → BLTNBR)
            // ============================================================
            WriteLog("--- Section 10: Lot/Serial Class Rename ---");
            // Acumatica doesn't use DB-level FK constraints, so direct PK update should work
            grandTotal += SafeExec(conn, "UPDATE InventoryItem SET LotSerClassID = 'BLTNBR' WHERE LotSerClassID = 'PIECENBR'", "InventoryItem.LotSerClassID");
            grandTotal += SafeExec(conn, "UPDATE INItemClass SET LotSerClassID = 'BLTNBR' WHERE LotSerClassID = 'PIECENBR'", "INItemClass.LotSerClassID");
            grandTotal += SafeExec(conn, "UPDATE INLotSerClassSegment SET LotSerClassID = 'BLTNBR' WHERE LotSerClassID = 'PIECENBR'", "INLotSerClassSegment.LotSerClassID");
            grandTotal += SafeExec(conn, "UPDATE INLotSerClass SET LotSerClassID = 'BLTNBR' WHERE LotSerClassID = 'PIECENBR'", "INLotSerClass.LotSerClassID");

            // ============================================================
            // SECTION 11: Cleanup orphaned PIECE UOM definition
            // ============================================================
            WriteLog("--- Section 11: Cleanup ---");
            // Only delete if no remaining references exist
            grandTotal += SafeExec(conn, @"
                IF NOT EXISTS (SELECT TOP 1 1 FROM InventoryItem WHERE BaseUnit = 'PIECE' OR SalesUnit = 'PIECE' OR PurchaseUnit = 'PIECE')
                AND NOT EXISTS (SELECT TOP 1 1 FROM INUnit WHERE FromUnit = 'PIECE' OR ToUnit = 'PIECE')
                    DELETE FROM CSUnit WHERE UnitID = 'PIECE'", "CSUnit.PIECE.Cleanup");

            WriteLog($"=== UomRenamePieceToYds: COMPLETE. {grandTotal} total rows affected. ===");
        }
    }

    private int SafeExec(Microsoft.Data.SqlClient.SqlConnection conn, string sql, string label)
    {
        try
        {
            using (var cmd = conn.CreateCommand())
            {
                cmd.CommandText = sql;
                cmd.CommandTimeout = 300; // 5 min timeout for large tables
                int rows = cmd.ExecuteNonQuery();
                string status = rows > 0 ? $"{rows} rows" : "0 rows (no-op)";
                WriteLog($"  {label}: {status}");
                return rows;
            }
        }
        catch (Exception ex)
        {
            WriteLog($"  {label}: SKIPPED — {ex.Message}");
            return 0;
        }
    }
}
